import type { DefaultFilters, Filters } from '../FiltersContext';
import type { IEvent } from '../../';

export const canFilterByEventTags = (filters: Filters, defaultFilters: DefaultFilters) =>
	filters.selectedEventTags.length > 0 && filters.selectedEventTags.length !== defaultFilters.eventTags.length;

export const filterByEventTags = (filters: Filters, defaultFilters: DefaultFilters) => (event: IEvent) =>
	// Only return true for events that match at least one selected tag.
	// If no specific tag filtering is applied, return true to allow all events to pass.
	canFilterByEventTags(filters, defaultFilters)
		? Array.isArray(event.tags) && event.tags.some((tag) => filters.selectedEventTags.includes(tag))
		: true;
