import type { DefaultFilters, Filters } from '../FiltersContext';
import type { IEvent } from '../../';

export const canFilterByEventType = (filters: Filters, defaultFilters: DefaultFilters) =>
	filters.selectedEventTypes.length > 0 && filters.selectedEventTypes.length !== defaultFilters.eventTypes.length;

export const filterByEventType = (filters: Filters, defaultFilters: DefaultFilters) => (event: IEvent) =>
	canFilterByEventType(filters, defaultFilters)
		? Array.isArray(event.eventType) && event.eventType.some((type) => filters.selectedEventTypes.includes(type))
		: true;
