import type { DefaultFilters, Filters } from '../FiltersContext';
import type { IEvent } from '../../';

export const canFilterByEventVenue = (filters: Filters, defaultFilters: DefaultFilters) =>
	filters.selectedEventLocations.length > 0 &&
	filters.selectedEventLocations.length !== defaultFilters.eventLocations.length;

export const filterByEventVenue = (filters: Filters, defaultFilters: DefaultFilters) => (event: IEvent) =>
	canFilterByEventVenue(filters, defaultFilters) ? filters.selectedEventLocations.includes(event.venue) : true;
